(()=>{
const SUPA='https://fzqpmpgbubpmongodcat.supabase.co';
const KEY='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZ6cXBtcGdidWJwbW9uZ29kY2F0Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc5NzI5MzIsImV4cCI6MjEwMzU0ODkzMn0.pLJfo5jpfMNRQCAbKC1dEW_INuBJan_eoyB_hWpChdw';
const SESSION='rc_music_dj_session_v1';
const defaults=[{id:'fifteen',label:'15 días',price:25},{id:'monthly',label:'Mensual',price:35},{id:'annual',label:'Anual',price:340}];
let host=null, selected='', proof='', proofName='', busy=false, method='yape', data={qr:'',number:'',plans:defaults};
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getSession(){try{return JSON.parse(sessionStorage.getItem(SESSION)||localStorage.getItem(SESSION)||'null')}catch{return null}}
async function rpc(name,body={}){const r=await fetch(`${SUPA}/rest/v1/rpc/${name}`,{method:'POST',headers:{apikey:KEY,Authorization:`Bearer ${KEY}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error(name);return r.json()}
function normalizePlans(value){if(!Array.isArray(value)||!value.length)return defaults;return defaults.map(d=>{const x=value.find(p=>p.plan_type===d.id||p.id===d.id||p.plan_id===d.id);const n=Number(x?.price_pen??x?.price??d.price);return {...d,price:Number.isFinite(n)?n:d.price}})}
async function loadData(){const [q,n,p]=await Promise.allSettled([rpc('get_subscription_qr'),rpc('get_subscription_yape_number'),rpc('get_subscription_plan_prices')]);data.qr=q.status==='fulfilled'?String(q.value||''):'';data.number=n.status==='fulfilled'?String(n.value||''):'';data.plans=p.status==='fulfilled'?normalizePlans(p.value):defaults;render()}
function css(){return `<style id="rc-plans-style">#rc-plans{position:fixed;inset:0;z-index:2147483000;overflow:auto;background:radial-gradient(circle at 15% 0%,rgba(218,0,255,.18),transparent 35%),#07070d;color:#fff;font-family:Inter,system-ui,sans-serif}#rc-plans *{box-sizing:border-box}.rcp-wrap{max-width:760px;margin:0 auto;padding:18px 16px 42px}.rcp-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.rcp-brand{font-weight:900;letter-spacing:.04em}.rcp-brand span{color:#b8ff3d}.rcp-close{border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.06);color:#fff;border-radius:12px;padding:9px 13px;font-weight:800}.rcp-card{border:1px solid rgba(0,229,255,.22);background:rgba(255,255,255,.045);border-radius:24px;padding:18px;margin-bottom:14px;box-shadow:0 18px 55px rgba(0,0,0,.22)}.rcp-title{font-size:28px;margin:0 0 7px}.rcp-muted{color:rgba(255,255,255,.58);font-size:13px;line-height:1.55}.rcp-plans{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:15px}.rcp-plan{border:1px solid rgba(0,229,255,.28);background:rgba(0,229,255,.08);color:#fff;border-radius:15px;padding:13px 7px;text-align:center;font-weight:800}.rcp-plan.sel{border-color:#b8ff3d;background:rgba(184,255,61,.18);box-shadow:0 0 0 2px rgba(184,255,61,.18)}.rcp-plan small{display:block;color:#b8ff3d;margin-top:5px;font-size:15px}.rcp-methods{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.rcp-method{flex:1;min-width:120px;border:1px solid rgba(255,255,255,.15);background:rgba(255,255,255,.05);color:#fff;border-radius:13px;padding:11px;font-weight:800}.rcp-method.sel{border-color:#00e5ff;background:rgba(0,229,255,.16);color:#7ff7ff}.rcp-yape{display:flex;align-items:center;gap:14px;background:#fff;color:#111;border-radius:15px;padding:12px;margin-top:13px}.rcp-yape img{width:112px;height:112px;object-fit:contain;border-radius:10px}.rcp-yape strong{display:block;margin-bottom:4px}.rcp-upload{display:block;border:1px dashed rgba(184,255,61,.55);color:#b8ff3d;background:rgba(184,255,61,.08);border-radius:13px;padding:13px;text-align:center;font-weight:900;margin-top:12px}.rcp-upload input{display:none}.rcp-proof{max-width:100%;max-height:170px;display:block;margin:12px auto 0;border-radius:12px;background:#fff;padding:4px}.rcp-send{width:100%;border:0;border-radius:14px;background:#b8ff3d;color:#07100a;padding:14px;font-weight:950;margin-top:12px}.rcp-send:disabled{opacity:.42}.rcp-msg{color:#7ff7ff;font-size:12px;line-height:1.5;margin-top:10px}.rcp-back{display:inline-flex;border:0;background:none;color:#7ff7ff;font-weight:800;padding:0;margin-bottom:15px}@media(max-width:560px){.rcp-plans{grid-template-columns:1fr}.rcp-yape{align-items:flex-start}.rcp-yape img{width:92px;height:92px}.rcp-title{font-size:24px}}
</style>`}
function render(){if(!host)return;host.innerHTML=css()+`<div class="rcp-wrap"><div class="rcp-top"><div class="rcp-brand">RC <span>music</span> _eventos</div></div><section class="rcp-card"><h1 class="rcp-title">Adquirir un plan</h1><p class="rcp-muted">Elige un plan, realiza el pago y envía tu comprobante para activar o renovar tu acceso.</p><div class="rcp-plans">${data.plans.map(p=>`<button class="rcp-plan ${selected===p.id?'sel':''}" data-plan="${esc(p.id)}">${esc(p.label)}<small>S/. ${Number(p.price).toFixed(2)}</small></button>`).join('')}</div></section><section class="rcp-card"><h2 style="margin:0;font-size:18px">Métodos de pago</h2><div class="rcp-methods"><button class="rcp-method ${method==='yape'?'sel':''}" data-method="yape">Yape</button><button class="rcp-method ${method==='mercado'?'sel':''}" data-method="mercado">Mercado Pago</button><button class="rcp-method ${method==='paypal'?'sel':''}" data-method="paypal">PayPal</button></div>${method==='yape'?`<div class="rcp-yape">${data.qr?`<img src="${esc(data.qr)}" alt="QR de Yape">`:''}<div><strong>Paga con Yape</strong>${data.number?`<span>Número: ${esc(data.number)}</span>`:''}<p class="rcp-muted" style="color:#333;margin:6px 0 0">Escanea el QR o usa el número y luego sube tu comprobante.</p></div></div>`:method==='paypal'?`<div class="rcp-yape" style="display:block"><strong>PayPal</strong><p style="margin:7px 0;color:#333">Realiza el pago en <b>paypal.me/rcmusiceventos</b> en USD y guarda tu comprobante.</p></div>`:`<div class="rcp-yape" style="display:block"><strong>Mercado Pago</strong><p style="margin:7px 0;color:#333">Selecciona este método y usa los datos de pago indicados por el administrador. Luego sube tu comprobante.</p></div>`}</section><section class="rcp-card"><p style="margin:0;font-weight:850">${selected?`Plan elegido: ${esc(data.plans.find(p=>p.id===selected)?.label||'')}`:'1. Elige el plan que pagaste'}</p><label class="rcp-upload">${busy?'Procesando…':'2. Subir comprobante'}<input id="rcp-file" type="file" accept="image/png,image/jpeg,image/webp"></label>${proof?`<img class="rcp-proof" src="${proof}" alt="Vista previa del comprobante">`:''}<button class="rcp-send" id="rcp-send" ${(!selected||!proof||busy)?'disabled':''}>${busy?'Enviando…':'3. Enviar comprobante'}</button><div id="rcp-msg" class="rcp-msg"></div></section></div>`;bind()}
function bind(){host.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{selected=b.dataset.plan;render()});host.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{method=b.dataset.method;render()});host.querySelector('#rcp-close').onclick=()=>{location.hash='#dj-login'};host.querySelector('#rcp-back').onclick=()=>{location.hash='#dj-login'};const file=host.querySelector('#rcp-file');file.onchange=()=>readFile(file.files?.[0]);host.querySelector('#rcp-send').onclick=send}
function readFile(file){if(!file)return;busy=true;render();const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(im.naturalWidth,im.naturalHeight));c.width=Math.max(1,im.naturalWidth*scale);c.height=Math.max(1,im.naturalHeight*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);proof=c.toDataURL('image/webp',.84);proofName=file.name;busy=false;render()};im.src=r.result};r.readAsDataURL(file)}
async function send(){const s=getSession(),token=s?.token||s?.session_token;if(!token){host.querySelector('#rcp-msg').textContent='Vuelve a ingresar al Panel DJ para enviar el comprobante.';return}busy=true;render();try{await rpc('submit_subscription_proof',{p_token:token,p_plan_type:selected,p_proof_image:proof});busy=false;render();host.querySelector('#rcp-msg').textContent='Comprobante enviado. El desarrollador revisará el pago y activará tu plan.'}catch{busy=false;render();host.querySelector('#rcp-msg').textContent='No se pudo enviar el comprobante. Inténtalo nuevamente.'}}
function open(){if(!host){host=document.createElement('div');host.id='rc-plans';document.body.appendChild(host)}document.getElementById('root')?.style.setProperty('display','none');render();loadData()}
function close(){host?.remove();host=null;document.getElementById('root')?.style.removeProperty('display')}
function route(){if(location.hash.slice(1)==='dj-plans')open();else if(host)close()}
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(b&&/adquirir\s+un\s+plan/i.test(b.textContent||'')){e.preventDefault();e.stopImmediatePropagation();location.hash='#dj-plans'}},true);
window.addEventListener('hashchange',route);route();
})();
